CREATE TABLE IF NOT EXISTS `hg_youban_publish_relay_channel` (`id` bigint NOT NULL AUTO_INCREMENT, `tenant_id` bigint NOT NULL DEFAULT 0, `tg_account_id` bigint NOT NULL DEFAULT 0, `channel_id` varchar(128) NOT NULL DEFAULT '', `target_chat_id` varchar(128) NOT NULL DEFAULT '', `title` varchar(255) NOT NULL DEFAULT '', `status` varchar(16) NOT NULL DEFAULT 'disabled', `health_status` varchar(16) NOT NULL DEFAULT 'unknown', `bot_permission_status` varchar(16) NOT NULL DEFAULT 'unknown', `cooldown_until` datetime NULL, `last_error` text, `in_flight_count` int NOT NULL DEFAULT 0, `last_used_at` datetime NULL, `created_at` datetime NULL, `updated_at` datetime NULL, `deleted_at` datetime NULL, PRIMARY KEY (`id`), UNIQUE KEY `uk_ybp_relay_channel_tenant_chat` (`tenant_id`,`target_chat_id`), KEY `idx_ybp_relay_channel_pick` (`tenant_id`,`status`,`health_status`,`cooldown_until`,`last_used_at`));
CREATE TABLE IF NOT EXISTS `hg_youban_publish_relay_media` (`id` bigint NOT NULL AUTO_INCREMENT, `tenant_id` bigint NOT NULL DEFAULT 0, `media_id` bigint NOT NULL DEFAULT 0, `purpose` varchar(16) NOT NULL DEFAULT '', `media_version` varchar(64) NOT NULL DEFAULT 'original', `relay_channel_id` bigint NOT NULL DEFAULT 0, `relay_chat_id` varchar(128) NOT NULL DEFAULT '', `message_id` bigint NOT NULL DEFAULT 0, `file_id` text NOT NULL, `status` varchar(16) NOT NULL DEFAULT 'uploading', `lease_token` varchar(64) NOT NULL DEFAULT '', `lease_until` datetime NULL, `last_error` text, `expires_at` datetime NULL, `created_at` datetime NULL, `updated_at` datetime NULL, PRIMARY KEY (`id`), UNIQUE KEY `uk_ybp_relay_media_key` (`tenant_id`,`media_id`,`purpose`,`media_version`), KEY `idx_ybp_relay_media_ready` (`tenant_id`,`media_id`,`purpose`,`status`), KEY `idx_ybp_relay_media_lease` (`status`,`lease_until`,`id`));
